import{_ as r,l,o as e,c as n,v as t,p,x as o,d as E,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"刻蚀模型进 OPC","description":"","frontmatter":{"title":"刻蚀模型进 OPC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-in-opc.md","filePath":"litho/etch-in-opc.md","lastUpdated":1789023840000}'),d={name:"litho/etch-in-opc.md"};function c(A,a,P,C,_,m){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="刻蚀模型进-opc" tabindex="-1">刻蚀模型进 OPC <a class="header-anchor" href="#刻蚀模型进-opc" aria-label="Permalink to &quot;刻蚀模型进 OPC&quot;">​</a></h1><div class="epigraph"><p>OPC 若停在显影轮廓，刻蚀还会按密度把边再挪一截；转印模型必须进同一条迭代，而不是事后加偏置。</p><footer>—— 对照计算光刻中「光学 + 胶 + 刻蚀」紧凑链的通称；负荷与偏置见刻蚀工程公开讨论</footer></div><p><a href="/litho/pw-opc">上一课</a>把名义点升级成工艺矩形上的 PV-band。缺口是：那条带默认画在抗蚀剂边上。反应离子刻蚀（以及后续硬掩模）按开口密度、深宽比和聚合物沉积再做一个邻域算子。本课钉刻蚀模型进 OPC。胶本身如何从空中像变成那条显影边，留给[下一课](/litho/resist-compact-model）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一条显影 CD，密线区与孤立线区刻完可以差出窗口的一截：微负载、大面积负载、侧面聚合物、以及 <a href="/litho/etch-loading-ar">ARDE</a> 把深度和横向偏置写成密度的函数。若 OPC 只让显影边贴目标，硅或金属上的最终 CD 仍随环境变。早期做法是在 OPC 后再加一层经验蚀刻偏置表——和规则 OPC 同一类破产：二维邻域组合表盖不住。</p><p>PW-OPC 的工艺点若不含刻蚀，窗口角上的「还剩的带」会在转印时被吃掉。问题是把刻蚀前向收成可调用的紧凑模型，嵌进碎片循环，而不是再写一篇腔体化学综述。</p><h3 id="转印是第二个邻域-不是常数偏置" tabindex="-1">转印是第二个邻域，不是常数偏置 <a class="header-anchor" href="#转印是第二个邻域-不是常数偏置" aria-label="Permalink to &quot;转印是第二个邻域，不是常数偏置&quot;">​</a></h3><p>光学邻域是数个波长；刻蚀邻域可以是微米到毫米（负载）叠加纳米级的侧面偏移。两种卷积核不同。把刻蚀当成「全场减 2 nm」只会修对一维标定线，修不对二维热区与 SRAM。</p><p><span class="marginnote">最终签核轮廓要写清：ADI 还是 AEI。PW-band 若只含 ADI，电学看到的是另一张图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>紧凑刻蚀模型吃显影多边形（或采样边），输出刻蚀后边。输入特征包括局部开口率、可见视野内的密度、线宽/间距、取向。校准用 ADI/AEI SEM 或电气 CD。模型进 OPC 后，EPE 对<strong>刻蚀后目标</strong>计算；工艺点可以含刻蚀漂移（时间、功率的代理），但全物理腔体模拟进不了全芯片迭代。</p><p>分层仍然必要：规则区用短程偏置加密度核；热区加更长程负载或补丁。刻蚀模型换腔、换硬掩模、换气体即作废，与光学模型独立校准、一起使用。</p><h3 id="与-pw-opc-的顺序" tabindex="-1">与 PW-OPC 的顺序 <a class="header-anchor" href="#与-pw-opc-的顺序" aria-label="Permalink to &quot;与 PW-OPC 的顺序&quot;">​</a></h3><p>先有能算的刻蚀前向，再把 AEI 目标放进多工艺点代价。反过来先做光学 PW、再贴刻蚀表，角点会双重计数或漏计。工程上常先光学+胶收敛，再打开刻蚀核微调，避免一开始变量耦合炸裂；签核必须是三者同时开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>碎片移动改掩模 → 空中像 → 显影边 → 刻蚀边。梯度（或差分）必须穿过刻蚀核，否则优化仍在修胶边。刻蚀核对小 jog 可能不光滑，MRC 与碎片长度要避免把噪声修进掩模。密度核是低通：它惩罚的是环境，不是单条边的高频衬线；因此刻蚀进 OPC 往往减少「为贴 ADI 而堆的无用衬线」，把修正预算留给真正进 AEI 的自由度。</p><p>负荷让大片空区与密区的横向蚀刻不同，SRAM 与逻辑边界成为热点。这与光学热区不完全重合：光学热区在禁戒节距，刻蚀热区在密度跳变。两类都要进同一张掩模。</p><p><span class="marginnote">紧凑刻蚀模型是拟合物，不是等离子体第一性原理。换机台配方等于换 OPC 版本。不要把论文里的 PIC 模拟当全芯片核。</span></p>',18)),(e(),p(h,null,{default:o(()=>[s(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20LR%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E7%A2%8E%E7%89%87%22%5D%20--%3E%20OPT%5B%22%E5%85%89%E5%AD%A6%2B%E8%83%B6%22%5D%0A%20%20OPT%20--%3E%20ADI%5B%22%E6%98%BE%E5%BD%B1%E8%BD%AE%E5%BB%93%22%5D%0A%20%20ADI%20--%3E%20ETCH%5B%22%E7%B4%A7%E5%87%91%E5%88%BB%E8%9A%80%E6%A0%B8%22%5D%0A%20%20ETCH%20--%3E%20AEI%5B%22%E5%88%BB%E8%9A%80%E5%90%8E%E8%BD%AE%E5%BB%93%22%5D%0A%20%20AEI%20--%3E%20EPE%5B%22%E5%AF%B9%E6%9C%80%E7%BB%88%E7%9B%AE%E6%A0%87%20EPE%20%2F%20PV%22%5D%0A%20%20EPE%20--%3E%20MASK%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 ALE/RIE 化学写进 OPC。随机孔洞、选择比崩溃不是均值刻蚀核能预测的。后课胶模型若不准，刻蚀核吃进去的 ADI 就是错的，误差会算到「刻蚀」头上。</p><p>不要发明供应商蚀刻模型的内部系数名。通称即可：密度核 + 短程偏置，校准到 AEI。</p><p><span class="marginnote">多重图形的每次曝光可以有不同刻蚀。OPC 链按层、按次分别校准，不要共用一张偏置表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最终 CD 在 AEI；只修 ADI 会把密度相关转印留给电学。</li><li>刻蚀是第二个邻域算子，常数偏置表覆盖不了二维负荷。</li><li>紧凑刻蚀核嵌进碎片循环，EPE 对刻蚀后目标计算。</li><li>光学热区与密度跳变热区要在同一张掩模上折中。</li><li>出处：OPC 通称的光学–胶–刻蚀链；刻蚀负荷公开工程讨论。</li></ul>',6))])}const D=r(d,[["render",c]]);export{u as __pageData,D as default};
